import{_ as s,a0 as r,w as u,s as a,I as l,x as n,a1 as t,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"SELinux 入門 | LCTT x X-CMD","titleTemplate":false,"description":"SELinux 入門 | LCTT (201605) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SELinux 入門 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SELinux 入門 | LCTT (201605) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201605/20160204 An Introduction to SELinux","title":"SELinux 入門","tag":"201605","desc":""},"relativePath":"201605/20160204 An Introduction to SELinux.md","filePath":"[post].md"}'),d={name:"201605/20160204 An Introduction to SELinux.md"};function x(L,i,S,m,E,f){const e=r("Link");return u(),a("div",null,[i[23]||(i[23]=l("h1",{id:"selinux-入門",tabindex:"-1"},[n("SELinux 入門 "),l("a",{class:"header-anchor",href:"#selinux-入門","aria-label":"Permalink to “SELinux 入門”"},"​")],-1)),l("p",null,[i[2]||(i[2]=n("回到 Kernel 2.6 時代，那時候引入了一個新的安全系統，用以提供訪問控制安全策略的機制。這個系統就是 ",-1)),t(e,{href:"http://selinuxproject.org/page/Main_Page"},{default:o(()=>[...i[0]||(i[0]=[n("Security Enhanced Linux (SELinux)",-1)])]),_:1}),i[3]||(i[3]=n("，它是由",-1)),t(e,{href:"https://www.nsa.gov/research/selinux/"},{default:o(()=>[...i[1]||(i[1]=[n("美國國家安全局（NSA）",-1)])]),_:1}),i[4]||(i[4]=n("貢獻的，它為 Linux 內核子系統引入了一個健壯的強制控制訪問（Mandatory Access Control）架構。",-1))]),i[24]||(i[24]=p(`<p>如果你在之前的 Linux 生涯中都禁用或忽略了 SELinux，這篇文章就是專門為你寫的：這是一篇對存在於你的 Linux 桌面或服務器之下的 SELinux 系統的介紹，它能夠限制權限，甚至消除程序或守護進程的脆弱性而造成破壞的可能性。</p><p>在我開始之前，你應該已經瞭解的是 SELinux 主要是紅帽 Red Hat Linux 以及它的衍生發行版上的一個工具。類似地， Ubuntu 和 SUSE（以及它們的衍生發行版）使用的是 AppArmor。SELinux 和 AppArmor 有顯著的不同。你可以在 SUSE，openSUSE，Ubuntu 等等發行版上安裝 SELinux，但這是項難以置信的挑戰，除非你十分精通 Linux。</p><p>説了這麼多，讓我來向你介紹 SELinux。</p><h3 id="dac-vs-mac" tabindex="-1">DAC vs. MAC <a class="header-anchor" href="#dac-vs-mac" aria-label="Permalink to “DAC vs. MAC”">​</a></h3><p>Linux 上傳統的訪問控制標準是自主訪問控制（Discretionary Access Control，DAC）。在這種形式下，一個軟件或守護進程以 User ID（UID）或 Set owner User ID（SUID）的身份運行，並且擁有該用户的目標（文件、套接字、以及其它進程）權限。這使得惡意代碼很容易運行在特定權限之下，從而取得訪問關鍵的子系統的權限。</p><p>另一方面，強制訪問控制（Mandatory Access Control，MAC）基於保密性和完整性強制信息的隔離以限制破壞。該限制單元獨立於傳統的 Linux 安全機制運作，並且沒有超級用户的概念。</p><h3 id="selinux-如何工作" tabindex="-1">SELinux 如何工作 <a class="header-anchor" href="#selinux-如何工作" aria-label="Permalink to “SELinux 如何工作”">​</a></h3><p>考慮一下 SELinux 的相關概念:</p><ul><li>主體（Subjects）</li><li>目標（Objects）</li><li>策略（Policy）</li><li>模式（Mode）</li></ul><p>當一個主體（Subject，如一個程序）嘗試訪問一個目標（Object，如一個文件），SELinux 安全服務器（SELinux Security Server，在內核中）從策略資料庫（Policy Database）中運行一個檢查。基於當前的模式（mode），如果 SELinux 安全服務器授予權限，該主體就能夠訪問該目標。如果 SELinux 安全服務器拒絕了權限，就會在 /var/log/messages 中記錄一條拒絕信息。</p><p>聽起來相對比較簡單是不是？實際上過程要更加複雜，但為了簡化介紹，只列出了重要的步驟。</p><h3 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to “模式”">​</a></h3><p>SELinux 有三個模式（可以由用户設置）。這些模式將規定 SELinux 在主體請求時如何應對。這些模式是：</p><ul><li>Enforcing （強制）— SELinux 策略強制執行，基於 SELinux 策略規則授予或拒絕主體對目標的訪問</li><li>Permissive （寬容）— SELinux 策略不強制執行，不實際拒絕訪問，但會有拒絕信息寫入日誌</li><li>Disabled （禁用）— 完全禁用 SELinux</li></ul><p><img src="https://www.linux.com/images/stories/66866/jack2-selinux_a.png" alt=""></p><p><em>圖 1：getenforce 命令顯示 SELinux 的狀態是 Enforcing 啓用狀態。</em></p><p>默認情況下，大部分系統的 SELinux 設置為 Enforcing。你要如何知道你的系統當前是什麼模式？你可以使用一條簡單的命令來查看，這條命令就是 <code>getenforce</code>。這個命令用起來難以置信的簡單（因為它僅僅用來報告 SELinux 的模式）。要使用這個工具，打開一個終端窗口並執行 <code>getenforce</code> 命令。命令會返回 Enforcing、Permissive，或者 Disabled（見上方圖 1）。</p><p>設置 SELinux 的模式實際上很簡單——取決於你想設置什麼模式。記住：<strong>永遠不推薦關閉 SELinux</strong>。為什麼？當你這麼做了，就會出現這種可能性：你磁盤上的文件可能會被打上錯誤的權限標籤，需要你重新標記權限才能修復。而且你無法修改一個以 Disabled 模式啓動的系統的模式。你的最佳模式是 Enforcing 或者 Permissive。</p><p>你可以從命令列或 <code>/etc/selinux/config</code> 文件更改 SELinux 的模式。要從命令列設置模式，你可以使用 <code>setenforce</code> 工具。要設置 Enforcing 模式，按下面這麼做：</p><ol><li>打開一個終端窗口</li><li>執行 <code>su</code> 然後輸入你的管理員密碼</li><li>執行 <code>setenforce 1</code></li><li>執行 <code>getenforce</code> 確定模式已經正確設置（圖 2）</li></ol><p><img src="https://www.linux.com/images/stories/66866/jack-selinux_b.png" alt=""></p><p><em>圖 2：設置 SELinux 模式為 Enforcing。</em></p><p>要設置模式為 Permissive，這麼做：</p><ol><li>打開一個終端窗口</li><li>執行 <code>su</code> 然後輸入你的管理員密碼</li><li>執行 <code>setenforce 0</code></li><li>執行 <code>getenforce</code> 確定模式已經正確設置（圖 3）</li></ol><p><img src="https://www.linux.com/images/stories/66866/jack-selinux_c.png" alt=""></p><p><em>圖 3：設置 SELinux 模式為 Permissive。</em></p><p>注：通過命令列設置模式會覆蓋 SELinux 配置文件中的設置。</p><p>如果你更願意在 SELinux 命令文件中設置模式，用你喜歡的編輯器打開那個文件找到這一行：</p><pre><code>SELINUX=permissive
</code></pre><p>你可以按你的偏好設置模式，然後保存文件。</p><p>還有第三種方法修改 SELinux 的模式（通過 bootloader），但我不推薦新用户這麼做。</p><h3 id="策略類型" tabindex="-1">策略類型 <a class="header-anchor" href="#策略類型" aria-label="Permalink to “策略類型”">​</a></h3><p>SELinux 策略有兩種：</p><ul><li>Targeted — 只有目標網絡進程（dhcpd，httpd，named，nscd，ntpd，portmap，snmpd，squid，以及 syslogd）受保護</li><li>Strict — 對所有進程完全的 SELinux 保護</li></ul><p>你可以在 <code>/etc/selinux/config</code> 文件中修改策略類型。用你喜歡的編輯器打開這個文件找到這一行：</p><pre><code>SELINUXTYPE=targeted
</code></pre><p>修改這個選項為 targeted 或 strict 以滿足你的需求。</p><h3 id="檢查完整的-selinux-狀態" tabindex="-1">檢查完整的 SELinux 狀態 <a class="header-anchor" href="#檢查完整的-selinux-狀態" aria-label="Permalink to “檢查完整的 SELinux 狀態”">​</a></h3><p>有個方便的 SELinux 工具，你可能想要用它來獲取你啓用了 SELinux 的系統的詳細狀態報告。這個命令在終端像這樣運行：</p><pre><code>sestatus -v
</code></pre><p>你可以看到像圖 4 那樣的輸出。</p><p><img src="https://www.linux.com/images/stories/66866/jack-selinux_d.png" alt=""></p><p><em>圖 4：sestatus -v 命令的輸出。</em></p><h3 id="僅是皮毛" tabindex="-1">僅是皮毛 <a class="header-anchor" href="#僅是皮毛" aria-label="Permalink to “僅是皮毛”">​</a></h3><p>和你預想的一樣，我只介紹了 SELinux 的一點皮毛。SELinux 的確是個複雜的系統，想要更紮實地理解它是如何工作的，以及瞭解如何讓它更好地為你的桌面或服務器工作需要更加地深入學習。我的內容還沒有覆蓋到疑難解答和創建自定義 SELinux 策略。</p>`,45)),l("p",null,[i[6]||(i[6]=n("SELinux 是所有 Linux 管理員都應該知道的強大工具。現在已經向你介紹了 SELinux，我強烈推薦你回到 Linux.com（當有更多關於此話題的文章發表的時候）或看看 ",-1)),t(e,{href:"https://www.nsa.gov/research/selinux/docs.shtml"},{default:o(()=>[...i[5]||(i[5]=[n("NSA SELinux 文檔",-1)])]),_:1}),i[7]||(i[7]=n(" 獲得更加深入的指南。",-1))]),l("p",null,[i[9]||(i[9]=n("LCTT - 相關閲讀：",-1)),t(e,{href:"http://vbird.dic.ksu.edu.tw/linux_basic/0440processcontrol_5.php"},{default:o(()=>[...i[8]||(i[8]=[n("鳥哥的 Linux 私房菜——程序管理與 SELinux 初探",-1)])]),_:1})]),i[25]||(i[25]=l("hr",null,null,-1)),l("p",null,[i[11]||(i[11]=n("via: ",-1)),t(e,{href:"https://www.linux.com/learn/docs/ldp/883671-an-introduction-to-selinux"},{default:o(()=>[...i[10]||(i[10]=[n("https://www.linux.com/learn/docs/ldp/883671-an-introduction-to-selinux",-1)])]),_:1})]),l("p",null,[i[15]||(i[15]=n("作者：",-1)),t(e,{href:"https://www.linux.com/community/forums/person/93"},{default:o(()=>[...i[12]||(i[12]=[n("Jack Wallen",-1)])]),_:1}),i[16]||(i[16]=n(" 譯者：",-1)),t(e,{href:"https://github.com/alim0x"},{default:o(()=>[...i[13]||(i[13]=[n("alim0x",-1)])]),_:1}),i[17]||(i[17]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:o(()=>[...i[14]||(i[14]=[n("wxy",-1)])]),_:1})]),l("p",null,[i[20]||(i[20]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[18]||(i[18]=[n("LCTT",-1)])]),_:1}),i[21]||(i[21]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:o(()=>[...i[19]||(i[19]=[n("Linux中國",-1)])]),_:1}),i[22]||(i[22]=n(" 榮譽推出",-1))])])}const b=s(d,[["render",x]]);export{w as __pageData,b as default};
